$ErrorActionPreference='Stop'
$assetRoot=Split-Path -Parent $PSScriptRoot;$componentRoot=Join-Path $assetRoot 'components-v01';$runtime='E:\R4D\perspective\p6-runtime\asset-artist'
$env:TEMP=Join-Path $runtime 'temp';$env:TMP=$env:TEMP
$config=Get-Content -LiteralPath (Join-Path $runtime 'inputs\accepted-p1\config.json') -Raw|ConvertFrom-Json
$manifest=Get-Content -LiteralPath (Join-Path $runtime 'inputs\accepted-p1\manifest.json') -Raw|ConvertFrom-Json;$h=$manifest.projection.nativeToSource
function Project([double]$x,[double]$y){$w=$h[2][0]*$x+$h[2][1]*$y+$h[2][2];@((($h[0][0]*$x+$h[0][1]*$y+$h[0][2])/$w),(($h[1][0]*$x+$h[1][1]*$y+$h[1][2])/$w))}
$cx=770.0;$cy=350.0;$rx=500.0;$ry=230.0;$apertureFactor=2.3
Add-Type -AssemblyName System.Drawing
$rawFile=Join-Path $componentRoot 'raw\receiver-master-v02.png';$raw=[System.Drawing.Bitmap]::new($rawFile)
if($raw.Width -ne1536 -or $raw.Height -ne1024){throw 'Mouth guide coordinates require the actual1536x1024 native output'}
$contour=[double[]]::new($raw.Width)
for($x=0;$x -lt $raw.Width;$x++){$start=$raw.Height;for($y=[int]$cy;$y -lt $raw.Height;$y++){$c=$raw.GetPixel($x,$y);$luma=.2126*$c.R+.7152*$c.G+.0722*$c.B;if($c.A -ge128 -and $luma -ge100 -and $c.R -ge130){$start=$y;break}};$contour[$x]=$start}
# The concrete front-rim luminance edge is median-smoothed over9 raw columns.
$smoothed=[double[]]::new($raw.Width)
for($x=0;$x -lt $raw.Width;$x++){$values=@();for($dx=-4;$dx -le4;$dx++){$j=[math]::Max(0,[math]::Min($raw.Width-1,$x+$dx));$values+=$contour[$j]};$smoothed[$x]=@($values|Sort-Object)[4]}
$instances=@();$nativeTransforms=@()
foreach($bucket in $config.board.buckets){$centre=Project $bucket.x $bucket.y;$left=Project ($bucket.x-$bucket.r) $bucket.y;$right=Project ($bucket.x+$bucket.r) $bucket.y;$captureRx=[math]::Sqrt([math]::Pow($right[0]-$left[0],2)+[math]::Pow($right[1]-$left[1],2))/2;$scale=$captureRx*$apertureFactor/$rx;$maxEllipse=0.0;$maxLuma=0.0;$minAlpha=255;for($i=0;$i -lt128;$i++){$theta=$i*2*[math]::PI/128;$p=Project ($bucket.x+$bucket.r*[math]::Cos($theta)) ($bucket.y+$bucket.r*[math]::Sin($theta));$u=$cx+($p[0]-$centre[0])/$scale;$v=$cy+($p[1]-$centre[1])/$scale;$ellipse=[math]::Pow(($u-$cx)/$rx,2)+[math]::Pow(($v-$cy)/$ry,2);$maxEllipse=[math]::Max($maxEllipse,$ellipse);$colour=$raw.GetPixel([int][math]::Round($u),[int][math]::Round($v));$maxLuma=[math]::Max($maxLuma,.2126*$colour.R+.7152*$colour.G+.0722*$colour.B);$minAlpha=[math]::Min($minAlpha,$colour.A)};$instances+=[ordered]@{id=$bucket.id;nativeCentre=@($bucket.x,$bucket.y);nativeCaptureRadius=$bucket.r;mouthCentreSource=$centre;captureRadiusXSource=$captureRx;uniformScale=$scale;holeRadiusXSource=($rx*$scale);holeRadiusYSource=($ry*$scale);captureSamples=128;captureMaxSafeEllipseNorm=$maxEllipse;captureMaxSampleLuma=$maxLuma;captureMinSampleAlpha=$minAlpha};$nativeTransforms+=$centre[0];$nativeTransforms+=$centre[1];$nativeTransforms+=$scale}
$raw.Dispose()
$warmup=[System.Drawing.Bitmap]::new(1,1);$warmup.Dispose();$refs=@([AppDomain]::CurrentDomain.GetAssemblies()|Where-Object{-not $_.IsDynamic -and $_.Location}|ForEach-Object Location|Select-Object -Unique)
Add-Type -ReferencedAssemblies $refs -TypeDefinition @"
using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
public static class P6ReceiverParts {
 static byte[] Pixels(Bitmap image){var d=image.LockBits(new Rectangle(0,0,image.Width,image.Height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);var p=new byte[Math.Abs(d.Stride)*image.Height];Marshal.Copy(d.Scan0,p,0,p.Length);image.UnlockBits(d);return p;}
 static double Sample(byte[] p,int w,int h,double x,double y,int c){if(x<0||y<0||x>w-1||y>h-1)return 0;int x0=(int)x,y0=(int)y,x1=Math.Min(x0+1,w-1),y1=Math.Min(y0+1,h-1);double fx=x-x0,fy=y-y0;double a=p[(y0*w+x0)*4+c]*(1-fx)+p[(y0*w+x1)*4+c]*fx,b=p[(y1*w+x0)*4+c]*(1-fx)+p[(y1*w+x1)*4+c]*fx;return a*(1-fy)+b*fy;}
 static void Save(byte[] pixels,int width,int height,string file){using(var result=new Bitmap(width,height,PixelFormat.Format32bppArgb)){var d=result.LockBits(new Rectangle(0,0,width,height),ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb);Marshal.Copy(pixels,0,d.Scan0,pixels.Length);result.UnlockBits(d);result.Save(file,ImageFormat.Png);}}
 static void Blend(byte[] output,int i,double b,double g,double r,double a){double oldA=output[i+3]/255.0,newA=a+oldA*(1-a);if(newA==0)return;output[i]=(byte)Math.Round((b*a+output[i]*oldA*(1-a))/newA);output[i+1]=(byte)Math.Round((g*a+output[i+1]*oldA*(1-a))/newA);output[i+2]=(byte)Math.Round((r*a+output[i+2]*oldA*(1-a))/newA);output[i+3]=(byte)Math.Round(newA*255);}
 public static void Prepare(string rawFile,string rearMaster,string frontMaster,string rearFrame,string frontFrame,double[] contour,double[] transforms,double cx,double cy){using(var raw=new Bitmap(rawFile)){var p=Pixels(raw);int w=raw.Width,h=raw.Height;var rear=new byte[p.Length];var front=new byte[p.Length];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int i=(y*w+x)*4;if(p[i+3]<16)continue;var target=y>=contour[x]?front:rear;for(int c=0;c<4;c++)target[i+c]=p[i+c];}Save(rear,w,h,rearMaster);Save(front,w,h,frontMaster);var rearFull=new byte[1536*1536*4];var frontFull=new byte[1536*1536*4];for(int item=0;item<transforms.Length;item+=3){double dx=transforms[item],dy=transforms[item+1],s=transforms[item+2];int minX=Math.Max(0,(int)Math.Floor(dx-cx*s)),maxX=Math.Min(1535,(int)Math.Ceiling(dx+(w-cx)*s)),minY=Math.Max(0,(int)Math.Floor(dy-cy*s)),maxY=Math.Min(1535,(int)Math.Ceiling(dy+(h-cy)*s));for(int y=minY;y<=maxY;y++)for(int x=minX;x<=maxX;x++){double u=cx+(x+0.5-dx)/s,v=cy+(y+0.5-dy)/s;if(u<0||u>=w||v<0||v>=h)continue;double a=Sample(p,w,h,u,v,3);if(a<16)continue;var target=v>=contour[Math.Min(w-1,(int)Math.Round(u))]?frontFull:rearFull;Blend(target,(y*1536+x)*4,Sample(p,w,h,u,v,0),Sample(p,w,h,u,v,1),Sample(p,w,h,u,v,2),a/255.0);}}Save(rearFull,1536,1536,rearFrame);Save(frontFull,1536,1536,frontFrame);}}
}
"@
